export interface RateLimitOptions {
  windowMs: number
  maxRequests: number
}

export interface Request {
  ip: string
}

export interface Response {
  status: (code: number) => Response
  json: (data: any) => void
}

export function createRateLimiter(options: RateLimitOptions) {
  const timestamps = new Map<string, number[]>()

  return (req: Request, res: Response, next: () => void) => {
    const now = Date.now()
    const cutoff = now - options.windowMs
    const ip = req.ip

    // Prune timestamps older than the window
    const current = (timestamps.get(ip) ?? []).filter((ts) => ts >= cutoff)

    if (current.length >= options.maxRequests) {
      const oldest = current[0]
      const retryAfterMs = oldest + options.windowMs - now
      res.status(429).json({ error: 'Too Many Requests', retryAfterMs })
      return
    }

    current.push(now)
    timestamps.set(ip, current)
    next()
  }
}
